+@using sv_d7b01a6b8cdb4b2299a8a800c7c0979b.Models
+@using sv_d7b01a6b8cdb4b2299a8a800c7c0979b.Services
+@implements IDisposable
+@inject IRecipeService RecipeService
+@inject ILogger<Recipes> Logger
+@inject NavigationManager Navigation
+
+<PageTitle>Recipes</PageTitle>
+
+<h1>Recipes — Cuisine @CuisineId</h1>
+
+<div class="mb-3">
+    <label class="form-label fw-bold">Sort by:</label>
+    <a href="@GetSortUrl("newest")" class="btn btn-sm @(Sort == "newest" ? "btn-primary" : "btn-outline-primary") me-1">Newest</a>
+    <a href="@GetSortUrl("popular")" class="btn btn-sm @(Sort == "popular" ? "btn-primary" : "btn-outline-primary")">Popular</a>
+</div>
+
+@if (errorMessage is not null)
+{
+    <div class="alert alert-danger d-flex align-items-center justify-content-between" role="alert">
+        <span>@errorMessage</span>
+        <button class="btn btn-outline-danger btn-sm ms-3" @onclick="RetryAsync">Retry</button>
+    </div>
+}
+else if (recipes is null)
+{
+    <div class="d-flex align-items-center my-4">
+        <div class="spinner-border text-primary me-3" role="status"></div>
+        <span>Loading recipes…</span>
+    </div>
+}
+else
+{
+    @if (isRefreshing)
+    {
+        <div class="alert alert-info py-1 px-3 d-inline-flex align-items-center mb-3" role="status">
+            <div class="spinner-border spinner-border-sm me-2" role="status"></div>
+            Refreshing…
+        </div>
+    }
+
+    <div class="row row-cols-1 row-cols-md-2 g-3">
+        @foreach (var recipe in GetSortedRecipes())
+        {
+            <div class="col">
+                <div class="card h-100">
+                    <div class="card-body">
+                        <h5 class="card-title">@recipe.Title</h5>
+                        <p class="card-text">@recipe.Description</p>
+                        <span class="badge bg-secondary">@recipe.PrepTimeMinutes min</span>
+                    </div>
+                </div>
+            </div>
+        }
+    </div>
+
+    @if (recipes.Count == 0)
+    {
+        <p class="text-muted mt-3">No recipes found for this cuisine.</p>
+    }
+}
+
+@code {
+    [Parameter] public int CuisineId { get; set; }
+    [SupplyParameterFromQuery(Name = "sort")] public string? Sort { get; set; }
+
+    private List<Recipe>? recipes;
+    private string? errorMessage;
+    private bool isRefreshing;
+    private int loadedCuisineId;
+
+    private CancellationTokenSource? loadCts;
+    private readonly CancellationTokenSource disposeCts = new();
+
+    protected override async Task OnParametersSetAsync()
+    {
+        if (CuisineId == loadedCuisineId && recipes is not null)
+        {
+            // Only the sort parameter changed — no need to reload.
+            return;
+        }
+
+        await LoadRecipesAsync();
+    }
+
+    private async Task LoadRecipesAsync()
+    {
+        // Cancel any in-flight load for the previous cuisine.
+        if (loadCts is not null)
+        {
+            await loadCts.CancelAsync();
+            loadCts.Dispose();
+        }
+
+        loadCts = CancellationTokenSource.CreateLinkedTokenSource(disposeCts.Token);
+        var cts = loadCts;
+
+        errorMessage = null;
+        isRefreshing = recipes is not null;
+
+        try
+        {
+            var result = await RecipeService.GetByCuisineAsync(CuisineId, cts.Token);
+
+            // Guard against a stale completion after cancellation.
+            if (cts.Token.IsCancellationRequested)
+                return;
+
+            recipes = result;
+            loadedCuisineId = CuisineId;
+        }
+        catch (OperationCanceledException) when (cts.Token.IsCancellationRequested)
+        {
+            // Expected — the user navigated away or switched cuisines.
+        }
+        catch (TimeoutException ex)
+        {
+            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", CuisineId);
+            errorMessage = "The request timed out. Please try again.";
+        }
+        catch (Exception ex)
+        {
+            Logger.LogError(ex, "Error loading recipes for cuisine {CuisineId}", CuisineId);
+            errorMessage = "Something went wrong while loading recipes. Please try again.";
+        }
+        finally
+        {
+            isRefreshing = false;
+        }
+    }
+
+    private async Task RetryAsync() => await LoadRecipesAsync();
+
+    private IEnumerable<Recipe> GetSortedRecipes()
+    {
+        if (recipes is null)
+            return Enumerable.Empty<Recipe>();
+
+        return Sort?.ToLowerInvariant() switch
+        {
+            "popular" => recipes.OrderBy(r => r.PrepTimeMinutes),
+            _ => recipes.OrderByDescending(r => r.Id),
+        };
+    }
+
+    private string GetSortUrl(string sort) =>
+        Navigation.GetUriWithQueryParameter("sort", sort);
+
+    public void Dispose()
+    {
+        disposeCts.Cancel();
+        disposeCts.Dispose();
+        loadCts?.Dispose();
+    }
+}
+

